INSERT INTO public.intake_question_sets(id,service_key,name,questions,sort,status)
SELECT key,key,replace(initcap(replace(key,'_',' ')),'And','&'),(SELECT jsonb_agg(jsonb_build_object('key','q'||ordinality,'text',value,'required',false) ORDER BY ordinality) FROM jsonb_array_elements_text(value) WITH ORDINALITY),row_number() OVER(ORDER BY key),CASE WHEN key IN ('internship','volunteering') THEN 'draft' ELSE 'published' END
FROM jsonb_each($sets${"diesel":["Delivery address and site type?","Litres needed per delivery and how often?","Tank size and access for a tanker?","Current supplier and price per litre, if you'd like a comparison?"],"power_solar_minigrid":["Site address and type (home, business, estate, community)?","Average monthly electricity and diesel spend?","Main appliances or equipment, and hours of use?","Do you own the site or the roof?","Preferred model: buy outright, pay monthly, or pay-as-you-use?"],"cng":["Vehicle make, model and year (or fleet size)?","Daily distance driven?","Where are the vehicles based?","Petrol or diesel today?"],"ev_fleet":["Are you a driver, a fleet or a property owner wanting to host chargers?","Location and parking available?","Number and type of vehicles?","Power supply at the site?"],"smart_metering":["Disco and meter type?","Number of meters or units?","What problem are you trying to solve (billing, theft, estimated bills)?"],"partners_investors":["Your organisation and role?","Which GET Energy line interests you?","What would you bring (capital, sites, technology, distribution)?","Your timeline?"],"energy_saving_equipment":["Which equipment?","Quantity and site?","Delivery or installation needed?"],"academy":["What is your highest qualification, and in what field?","Do you have any hands-on electrical, solar, mechanical or automotive experience? If yes, how many years and what kind of work?","What do you want this training to help you do: get a job, grow in your current job, start your own business, or something else?","Are you currently employed? If yes, what is your role, and is your employer likely to sponsor your training?","Which city are you in, and can you attend practical sessions in person at our B16 Training Centre?","Which days and times suit you best: weekdays, weekends, or evenings?","Would you need a scholarship, sponsorship or loan to take part?","Is there anything we should know to support you during training, such as accessibility needs?"],"careers":["Why do you want to work in energy, and why with GET Energy?","Describe a project or job where you solved a practical problem. What did you do, and what was the result?","Which of these have you worked with: solar PV, batteries or inverters, generators, metering, CNG or fuel, EVs, customer service, sales? Give one example.","How do you keep yourself and others safe at work? Give a real example.","Where are you based, and are you willing to travel to sites?","When could you start, and what notice period do you have?","What salary range are you expecting?"],"corporate_training":["Which topics do you need (for example solar, electrical safety, energy audit, CNG, EV, HSE, leadership)?","How many staff, and in what roles?","What should they be able to do after the training?","Do they need an assessment, a certificate of completion, or preparation for an external certification?","Preferred dates, duration and delivery mode (on-site, at B16, online)?","Who approves training spend, and is there a budget range?"],"internship":["What is your name?","What email or phone number should the team use to contact you?","Where are you based?","What is your field of study or which skills would you like to contribute?","When are you available?","What do you hope to gain?"],"volunteering":["What is your name?","What email or phone number should the team use to contact you?","Where are you based?","What is your field of study or which skills would you like to contribute?","When are you available?","What do you hope to gain?"]}$sets$::jsonb);
