CREATE FUNCTION public.intake_service_for(p_type text,p_service text,p_details jsonb) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE c text=lower(coalesce(p_type,'')||' '||coalesce(p_service,'')||' '||coalesce(p_details::text,'')); k text=p_details->>'intake_service_key'; BEGIN
IF k IN ('academy','careers','diesel','power_solar_minigrid','cng','ev_fleet','smart_metering','partners_investors','energy_saving_equipment','corporate_training','internship','volunteering') THEN RETURN k; END IF;
IF p_type='academy-corporate' THEN RETURN 'corporate_training'; END IF;
IF p_type IN ('academy-application','academy-waitlist','academy-certification','training') THEN RETURN 'academy'; END IF;
IF p_type='careers' THEN RETURN CASE WHEN c LIKE '%volunteer%' THEN 'volunteering' WHEN c LIKE '%intern%' THEN 'internship' ELSE 'careers' END; END IF;
IF p_type IN ('contact','whatsapp','academy-support','bills') THEN RETURN NULL; END IF;
IF c ~ 'equipment|energy-saving' THEN RETURN 'energy_saving_equipment'; END IF;
IF c ~ 'partner|invest|eea|e-commerce' THEN RETURN 'partners_investors'; END IF;
IF c ~ 'meter' THEN RETURN 'smart_metering'; END IF;
IF c ~ 'cng' THEN RETURN 'cng'; END IF;
IF c ~ '\mev\M|ev-|charging|fleet|host-site' THEN RETURN 'ev_fleet'; END IF;
IF c ~ 'diesel|fuel' THEN RETURN 'diesel'; END IF;
IF c ~ 'paas|power.as.a.service|solar|renewables|bess|mini.grid|community|battery storage' THEN RETURN 'power_solar_minigrid'; END IF;
RETURN NULL; END $$;
CREATE FUNCTION public.attach_intake_request() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb=to_jsonb(NEW); v_ref text; k text; BEGIN
v_ref=coalesce(r->>'reference',r->>'request_reference');
IF TG_TABLE_NAME='service_requests' THEN k=public.intake_service_for(r->>'request_type',r->>'service_name',r->'details'); END IF;
INSERT INTO public.intake_requests(reference,request_id,request_table,service_key,user_id) VALUES(v_ref,NEW.id,TG_TABLE_NAME,k,(r->>'user_id')::uuid) ON CONFLICT(reference) DO NOTHING;
RETURN NEW; END $$;
CREATE TRIGGER service_intake AFTER INSERT ON public.service_requests FOR EACH ROW EXECUTE FUNCTION public.attach_intake_request();
CREATE TRIGGER electricity_intake AFTER INSERT ON public.electricity_token_requests FOR EACH ROW EXECUTE FUNCTION public.attach_intake_request();
INSERT INTO public.intake_requests(reference,request_id,request_table,service_key,user_id) SELECT reference,id,'service_requests',public.intake_service_for(request_type,service_name,details),user_id FROM public.service_requests WHERE deleted_at IS NULL ON CONFLICT DO NOTHING;
INSERT INTO public.intake_requests(reference,request_id,request_table,user_id) SELECT request_reference,id,'electricity_token_requests',user_id FROM public.electricity_token_requests ON CONFLICT DO NOTHING;
CREATE FUNCTION public.submit_sophia_intake(p_thread_id uuid,p_visitor_token text,p_service_key text,p_contact jsonb,p_answers jsonb,p_bucket text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ref text; token text; saved integer; BEGIN
IF NOT EXISTS(SELECT 1 FROM public.sophia_threads WHERE id=p_thread_id AND visitor_token=p_visitor_token) THEN RAISE EXCEPTION 'Conversation not found'; END IF;
IF NOT public.electricity_hit_rate_limit('sophia-intake:'||left(p_bucket,100),5,600) THEN RAISE EXCEPTION 'Too many submissions'; END IF;
IF p_service_key IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.intake_question_sets WHERE service_key=p_service_key) THEN RAISE EXCEPTION 'Unknown service'; END IF;
IF EXISTS(SELECT 1 FROM public.service_requests WHERE request_type='sophia' AND details->>'thread_id'=p_thread_id::text AND deleted_at IS NULL) THEN RAISE EXCEPTION 'An enquiry is already saved for this conversation'; END IF;
ref=public.submit_service_request('sophia',left(p_contact->>'service',160),p_contact->>'contact_name',coalesce(p_contact->>'contact_email',''),coalesce(p_contact->>'contact_phone',''),coalesce(p_contact->>'company',''),coalesce(p_contact->>'location',''),jsonb_build_object('source','SOPHIA','thread_id',p_thread_id,'summary',p_contact->>'summary','intake_service_key',p_service_key));
IF ref='RATE_LIMITED' OR ref IS NULL THEN RAISE EXCEPTION 'Request could not be saved'; END IF;
token=public.issue_intake_token(ref);
saved=public.save_intake_answers(ref,token,NULL,p_bucket,p_answers,'sophia');
RETURN jsonb_build_object('reference',ref,'saved',saved); END $$;
REVOKE ALL ON FUNCTION public.submit_sophia_intake(uuid,text,text,jsonb,jsonb,text) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.submit_sophia_intake(uuid,text,text,jsonb,jsonb,text) TO service_role;